To align with our repository's testing standards, let's add regression tests to verify that the validator asserts the exact list of expected check IDs in strict byte-order, fails closed gracefully when passed null/malformed/non-record inputs, and records explicit invalid-type diagnostics when array fields have invalid types.

```javascript
  test('validator asserts the exact list of expected check IDs in strict byte-order and all checks pass', async () => {
    const { validatePostAttemptMsRevealGatePolicy } = await import(
      '../build-post-attempt-ms-reveal-gate-policy.mjs'
    );
    const validation = validatePostAttemptMsRevealGatePolicy({
      policy: result.policy,
      fixtures: result.fixtures,
      inputs: result.inputs,
    });

    expect(validation.validator_status).toBe('pass');
    const checkIds = validation.checks.map((check) => check.id);
    expect(checkIds).toEqual([
      'dependency_artifacts_loaded_and_passing',
      'eligibility_states_exact_and_non_scoring',
      'event_receipt_model_exact',
      'pre_attempt_visibility_and_payload_leakage_blocked',
      'asset_delivery_exact_and_fetch_protected',
      'frontend_preload_and_static_exposure_blocked',
      'teacher_admin_preview_role_gate_enforced',
      'manual_reveal_requires_attempt_confirmation',
      'display_policy_and_missing_states_fail_closed',
      'self_assessment_only_no_awarded_mark_wording',
      'fixtures_cover_required_states_and_validate',
      'forbidden_side_effects_absent',
    ]);
    for (const check of validation.checks) {
      expect(check.status).toBe('pass');
    }
  });

  test('validator fails closed gracefully when passed null, malformed, or non-record inputs', async () => {
    const { validatePostAttemptMsRevealGatePolicy } = await import(
      '../build-post-attempt-ms-reveal-gate-policy.mjs'
    );
    const validationNull = validatePostAttemptMsRevealGatePolicy(null);
    expect(validationNull.validator_status).toBe('fail');
    expect(validationNull.errors).toContain('policy_record_required');

    const validationEmpty = validatePostAttemptMsRevealGatePolicy({});
    expect(validationEmpty.validator_status).toBe('fail');
    expect(validationEmpty.errors).toContain('policy_record_required');

    const validationMalformed = validatePostAttemptMsRevealGatePolicy({
      policy: 'not-a-record',
      fixtures: [],
      inputs: null,
    });
    expect(validationMalformed.validator_status).toBe('fail');
    expect(validationMalformed.errors).toContain('policy_record_required');
  });

  test('validator fails closed with invalid-type diagnostics when array fields have invalid types', async () => {
    const { validatePostAttemptMsRevealGatePolicy } = await import(
      '../build-post-attempt-ms-reveal-gate-policy.mjs'
    );
    const malformedPolicy = {
      ...cloneJson(result.policy),
      reveal_eligibility_states: 'not-an-array',
      event_receipt_model: {},
      source_artifacts: 42,
    };
    const malformedFixtures = {
      ...cloneJson(result.fixtures),
      fixtures: 'not-an-array',
    };

    const validation = validatePostAttemptMsRevealGatePolicy({
      policy: malformedPolicy,
      fixtures: malformedFixtures,
      inputs: result.inputs,
    });

    expect(validation.validator_status).toBe('fail');
    expect(validation.errors).toContain('reveal_eligibility_states_invalid_type');
    expect(validation.errors).toContain('event_receipt_model_invalid_type');
    expect(validation.errors).toContain('source_artifacts_invalid_type');
    expect(validation.errors).toContain('fixtures_invalid_type');
  });

```

